#include "re3_codec.h"
#include <stdio.h>
int main(int argc,char**argv){re3c_model m;re3c_u32 b,c,k,total=0u,resolved=0u;int r;if(argc!=2){fprintf(stderr,"usage: %s file.EMD\n",argv[0]);return 2;}re3c_model_init(&m);r=re3c_open_file(&m,argv[1]);if(r!=RE3C_OK){fprintf(stderr,"open: %s\n",re3c_result_string(r));return 1;}for(b=0;b<RE3C_BANK_COUNT;b++){const re3c_anim_bank*ab=&m.banks[b];if(!ab->present)continue;for(c=0;c<ab->clip_count;c++)for(k=0;k<ab->clips[c].key_count;k++){re3c_key_resolution q;total++;r=re3c_resolve_key(&m,b,c,k,&q);if(r==RE3C_OK){resolved++;if(q.pose_available){re3c_pose p;r=re3c_decode_pose_by_key(&m,b,c,k,&p);if(r!=RE3C_OK){fprintf(stderr,"pose fail bank=%u clip=%u key=%u: %s\n",(unsigned)b,(unsigned)c,(unsigned)k,re3c_result_string(r));re3c_model_close(&m);return 1;}}}}}printf("key resolution total=%u resolved=%u\n",(unsigned)total,(unsigned)resolved);re3c_model_close(&m);return total==resolved?0:1;}
